pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {airPort} from "../src/airPort.sol";

contract InvMutTest is Test {
    airPort c;

    function setUp() public {
        c = new airPort();
    }

    function testFuzz_property(address from, address to0, address to1, uint256 amount) public {
        vm.assume(to0 != to1);
        vm.assume(to0 != address(0));
        vm.assume(to1 != address(0));
        amount = bound(amount, 0, type(uint128).max);

        RecordingReceiver recorder = new RecordingReceiver();
        address[] memory tos = new address[](2);
        tos[0] = to0;
        tos[1] = to1;

        bool ok = true;
        try c.transfer(from, address(recorder), tos, amount) returns (bool) {
        } catch {
            ok = false;
        }

        assertTrue(ok && recorder.count() == 2 && recorder.recipient(1) == to1);
    }
}

contract RecordingReceiver {
    address[] internal _recipients;

    function transferFrom(address, address to, uint256) external returns (bool) {
        _recipients.push(to);
        return true;
    }

    function count() external view returns (uint256) {
        return _recipients.length;
    }

    function recipient(uint256 i) external view returns (address) {
        return _recipients[i];
    }
}
